mapper.select:
select   st_pptn_r_ab.stcd,convert(varchar(19), st_pptn_r_ab.tm,120) as tm,st_pptn_r_ab.drp,st_pptn_r_ab.type,st_pptn_r_ab.note,st_pptn_r_ab.content,st_pptn_r_ab.marks,st_pptn_r_ab.stcddis,st_pptn_r_ab.stcddisdrp,st_pptn_r_ab.status, ST_STBPRP_B.STNM,ST_STBPRP_B.LGTD,ST_STBPRP_B.LTTD,ST_STBPRP_B.STLC,ST_SCREENINGRULES.NAME from ST_PPTN_R_AB
inner join ST_STBPRP_B on ST_PPTN_R_AB.STCD=ST_STBPRP_B.STCD
inner join ST_SCREENINGRULES on ST_PPTN_R_AB.TYPE=ST_SCREENINGRULES.id


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



         and ST_PPTN_R_AB.type in

            #{type}



        and ST_PPTN_R_AB.status = #{status}


        and ST_PPTN_R_AB.content = #{content}



        and ST_STBPRP_B.STLC= #{datasource}







order by  tm desc

select   ST_PPTN_R_AB.*,ST_STBPRP_B.STNM from
(
SELECT *, ROW_NUMBER() OVER(ORDER BY tm) AS rn
FROM
(
    select * from ST_PPTN_R_AB


             and TM >= #{stime} 


             and TM <= #{etime} 


            and ST_PPTN_R_AB.STCD in

                #{stcd}



            and ST_PPTN_R_AB.type = #{pathname}


            and ST_PPTN_R_AB.status = #{status}


            and ST_PPTN_R_AB.content = #{datasource}

     and ST_PPTN_R_AB.type in('1','3','5','6','7')   and ST_PPTN_R_AB.content='minute'


    union all

    select * from ST_PPTN_R_AB


             and TM >= #{stime} 


             and TM <= #{etime} 


            and ST_PPTN_R_AB.STCD in

                #{stcd}



            and ST_PPTN_R_AB.type = #{pathname}


            and ST_PPTN_R_AB.status = #{status}


            and ST_PPTN_R_AB.content = #{datasource}

        and ST_PPTN_R_AB.type in('2','4')   and ST_PPTN_R_AB.content='day'

)
as allData


)  ST_PPTN_R_AB  inner join  ST_STBPRP_B on ST_PPTN_R_AB.STCD=ST_STBPRP_B.STCD


        and rn between #{startindex}+1 and #{startindex}+#{pagesize}


order by  tm asc

select   count(*) from
(
select * from ST_PPTN_R_AB


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.type = #{pathname}


        and ST_PPTN_R_AB.status = #{status}


        and ST_PPTN_R_AB.content = #{datasource}

    and ST_PPTN_R_AB.type in('1','3','5','6','7')   and ST_PPTN_R_AB.content='minute'


union all

select * from ST_PPTN_R_AB


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.type = #{pathname}


        and ST_PPTN_R_AB.status = #{status}


        and ST_PPTN_R_AB.content = #{datasource}

    and ST_PPTN_R_AB.type in('2','4')   and ST_PPTN_R_AB.content='day'

)
as allData

select   alldata.TYPE,ST_SCREENINGRULES.NAME,alldata.ROWSCOUNT from ST_SCREENINGRULES
left join (
select TYPE,COUNT(*) as ROWSCOUNT from ST_PPTN_R_AB
inner join ST_STBPRP_B  on ST_PPTN_R_AB.STCD=ST_STBPRP_B.STCD


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}


        and ST_STBPRP_B.STLC= #{stlc}


group by ST_PPTN_R_AB.TYPE
) as alldata
on alldata.TYPE=ST_SCREENINGRULES.id


        and ST_SCREENINGRULES.CONTENT LIKE   '%'+#{pathname}+'%'

select  STLC,COUNT(*) as ROWSCOUNT from ST_PPTN_R_AB
inner join ST_STBPRP_B  on ST_PPTN_R_AB.STCD=ST_STBPRP_B.STCD


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}


        and ST_STBPRP_B.STLC= #{stlc}


group by ST_STBPRP_B.STLC

select year(tm) as name,COUNT(*) as ROWSCOUNT from ST_PPTN_R_AB
inner join ST_STBPRP_B  on ST_PPTN_R_AB.STCD=ST_STBPRP_B.STCD


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}


        and ST_STBPRP_B.STLC= #{stlc}


group by year(tm)
order by year(tm) asc

select   alldata.TYPE,ST_SCREENINGRULES.NAME,alldata.ROWSCOUNT from ST_SCREENINGRULES
left join (
select TYPE,COUNT(*) as ROWSCOUNT from ST_PPTN_R_AB
inner join ST_STBPRP_B  on ST_PPTN_R_AB.STCD=ST_STBPRP_B.STCD


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}


        and ST_STBPRP_B.STLC= #{stlc}

    and ST_PPTN_R_AB.type in('1','3','5','6','7') and ST_PPTN_R_AB.content='minute'


group by ST_PPTN_R_AB.TYPE

union all

select TYPE,COUNT(*) as ROWSCOUNT from ST_PPTN_R_AB
inner join ST_STBPRP_B  on ST_PPTN_R_AB.STCD=ST_STBPRP_B.STCD


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}


        and ST_STBPRP_B.STLC= #{stlc}

    and ST_PPTN_R_AB.type in('2','4') and ST_PPTN_R_AB.content='day'

group by ST_PPTN_R_AB.TYPE


) as alldata
on alldata.TYPE=ST_SCREENINGRULES.id


        and ST_SCREENINGRULES.CONTENT LIKE   '%'+#{pathname}+'%'

   and ST_SCREENINGRULES.marks='1'

order by ordernum asc

select STLC,COUNT(*) as ROWSCOUNT from ST_STBPRP_B
inner join (
select * from ST_PPTN_R_AB


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}

    and ST_PPTN_R_AB.type in('1','3','5','6','7') and ST_PPTN_R_AB.content='minute'

union  all
select * from ST_PPTN_R_AB


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}

    and ST_PPTN_R_AB.type in('2','4') and ST_PPTN_R_AB.content='day'

) as  alldata
on alldata.STCD=ST_STBPRP_B.STCD


        and ST_STBPRP_B.STLC= #{stlc}


group by ST_STBPRP_B.STLC

select year(tm) as name,COUNT(*) as ROWSCOUNT from
(
select *  from ST_PPTN_R_AB


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}

    and ST_PPTN_R_AB.type in('1','3','5','6','7') and ST_PPTN_R_AB.content='minute'

union  all
select *  from ST_PPTN_R_AB


         and TM >= #{stime} 


         and TM <= #{etime} 


        and ST_PPTN_R_AB.STCD in

            #{stcd}



        and ST_PPTN_R_AB.CONTENT = #{pathname}

    and ST_PPTN_R_AB.type in('2','4') and ST_PPTN_R_AB.content='day'

) as allData
inner join
ST_STBPRP_B
on allData.STCD=ST_STBPRP_B.STCD


        and ST_STBPRP_B.STLC= #{stlc}


group by year(tm)
order by year(tm) asc

mapper.update:
update ST_PPTN_R_AB


        STATUS= #{STATUS},


where stcd = #{STCD} and tm= #{TM} and type=#{TYPE} and content=#{CONTENT}

mapper.delete:
delete from ST_PPTN_R_AB
where

    (
        stcd = #{item.STCD}
     AND  tm = #{item.TM}
     AND type = #{item.TYPE}
     AND content = #{item.CONTENT}
    )
